<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { detalleFiscalizacion,detallePas,listarExpedientesPas,listarFiscalizaciones,registrarFiscalizacion,type ExpedientePas,type Fiscalizacion,type Options } from '../services/pas'
const tab=ref<'fiscalizaciones'|'expedientes'>('fiscalizaciones'),fiscalizaciones=ref<Fiscalizacion[]>([]),expedientes=ref<ExpedientePas[]>([]),options=ref<Options>({tipos_accion:[],resultados:[],estados_pas:[],anios:[]}),total=ref(0),lastPage=ref(1),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),detail=ref<Fiscalizacion|ExpedientePas|null>(null),pdf=ref<File|null>(null)
const filters=reactive({criterio:'',tipo_accion:'',resultado:'',estado_pas:'',anio:new Date().getFullYear(),page:1}),form=reactive({numero_fiscalizacion:'',tipo_accion:'',fecha_accion:new Date().toISOString().slice(0,10),descripcion_hechos:'',tiene_plazo_subsanacion:false,fecha_limite_subsanacion:''})
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=tab.value==='fiscalizaciones'?await listarFiscalizaciones(filters):await listarExpedientesPas(filters);total.value=r.total;lastPage.value=r.last_page;options.value=r.options;if(tab.value==='fiscalizaciones')fiscalizaciones.value=r.data as Fiscalizacion[];else expedientes.value=r.data as ExpedientePas[]}catch(e){error.value=message(e)}finally{loading.value=false}}
function change(value:'fiscalizaciones'|'expedientes'){tab.value=value;load(1)}function open(){Object.assign(form,{numero_fiscalizacion:'',tipo_accion:'',fecha_accion:new Date().toISOString().slice(0,10),descripcion_hechos:'',tiene_plazo_subsanacion:false,fecha_limite_subsanacion:''});pdf.value=null;modal.value=true}
async function save(){if(!form.numero_fiscalizacion||!form.tipo_accion||!form.fecha_accion||!form.descripcion_hechos||!pdf.value){error.value='Complete los datos obligatorios y adjunte el acta de fiscalización.';return}if(form.tiene_plazo_subsanacion&&(!form.fecha_limite_subsanacion||form.fecha_limite_subsanacion<=form.fecha_accion)){error.value='La fecha límite debe ser posterior a la fecha de la acción.';return}const data=new FormData();Object.entries(form).forEach(([k,v])=>{if(v!==''&&v!==false)data.append(k,v===true?'1':String(v))});data.append('documento_pdf',pdf.value);saving.value=true;error.value='';try{await registrarFiscalizacion(data);modal.value=false;success.value='Fiscalización registrada correctamente.';await load(1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function show(item:Fiscalizacion|ExpedientePas){try{detail.value=tab.value==='fiscalizaciones'?await detalleFiscalizacion(item.id):await detallePas(item.id)}catch(e){error.value=message(e)}}function choose(e:Event){pdf.value=(e.target as HTMLInputElement).files?.[0]||null}function money(v?:number){return new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(v||0)}function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / MAT / PAS</nav><header class="hero"><div class="mark">PAS</div><div><small>MAT · LEGAL</small><h1>Procedimiento Administrativo Sancionador</h1><p>Fiscalización, medidas correctivas y seguimiento de expedientes SUNASS.</p></div><strong>{{total}} registros</strong><button v-if="tab==='fiscalizaciones'" @click="open">+ Nueva fiscalización</button></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><div class="tabs"><button :class="{active:tab==='fiscalizaciones'}" @click="change('fiscalizaciones')">Fiscalizaciones</button><button :class="{active:tab==='expedientes'}" @click="change('expedientes')">Expedientes PAS</button></div>
<section class="filters"><label>Buscar<input v-model.trim="filters.criterio" placeholder="Número o descripción" @keyup.enter="load(1)"></label><template v-if="tab==='fiscalizaciones'"><label>Tipo<select v-model="filters.tipo_accion"><option value="">Todos</option><option v-for="x in options.tipos_accion" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Resultado<select v-model="filters.resultado"><option value="">Todos</option><option v-for="x in options.resultados" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label></template><template v-else><label>Estado<select v-model="filters.estado_pas"><option value="">Todos</option><option v-for="x in options.estados_pas" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Año<select v-model="filters.anio"><option v-for="x in options.anios" :key="x" :value="x">{{x}}</option></select></label></template><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando información…</div>
<section v-else-if="tab==='fiscalizaciones'" class="cards"><article v-for="item in fiscalizaciones" :key="item.id"><header><b>{{item.numero_fiscalizacion}}</b><em :class="item.resultado.toLowerCase()">{{item.resultado_label||item.resultado}}</em></header><small>{{item.tipo_accion_label||item.tipo_accion}} · {{item.fecha_accion}}</small><p>{{item.descripcion_hechos}}</p><dl><div><dt>Subsanación</dt><dd>{{item.fecha_limite_subsanacion||'Sin plazo'}}</dd></div><div><dt>Medidas</dt><dd>{{item.medidas_correctivas?.length||0}}</dd></div><div><dt>Estado</dt><dd>{{item.estado}}</dd></div></dl><footer><span v-if="item.puede_crear_pas">Requiere iniciar PAS</span><button @click="show(item)">Ver seguimiento</button></footer></article><div v-if="!fiscalizaciones.length" class="empty">No se encontraron fiscalizaciones.</div></section>
<section v-else class="table"><header><span>Expediente</span><span>Fiscalización</span><span>Resolución inicio</span><span>Caducidad</span><span>Sanción / multa</span><span>Estado</span><span></span></header><article v-for="item in expedientes" :key="item.id"><b>{{item.numero_expediente}}</b><span>{{item.fiscalizacion?.numero_fiscalizacion||'—'}}</span><div><b>{{item.res_inicio_numero||'Pendiente'}}</b><small>{{item.res_inicio_fecha}}</small></div><span :class="{danger:(item.dias_para_caducidad||99)<=30}">{{item.dias_para_caducidad==null?'—':item.dias_para_caducidad+' días'}}</span><span>{{item.tipo_sancion||'—'}}<small v-if="item.multa_soles">{{money(item.multa_soles)}}</small></span><em>{{item.estado_label||item.estado_pas}}</em><button @click="show(item)">Ver ficha</button></article><div v-if="!expedientes.length" class="empty">No se encontraron expedientes PAS.</div></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>NUEVA ACTUACIÓN</small><h2>Registrar fiscalización</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Número de fiscalización *<input v-model.trim="form.numero_fiscalizacion" maxlength="50"></label><label>Tipo de acción *<select v-model="form.tipo_accion"><option value="">Seleccione</option><option value="SUPERVISION">Supervisión</option><option value="FISCALIZACION">Fiscalización</option><option value="REQUERIMIENTO">Requerimiento</option></select></label><label>Fecha de acción *<input v-model="form.fecha_accion" type="date"></label><label class="check"><input v-model="form.tiene_plazo_subsanacion" type="checkbox"> Otorga plazo de subsanación</label><label v-if="form.tiene_plazo_subsanacion">Fecha límite *<input v-model="form.fecha_limite_subsanacion" type="date"></label></div><label>Descripción de los hechos *<textarea v-model.trim="form.descripcion_hechos" maxlength="1000" rows="5"></textarea></label><label>Acta de fiscalización PDF *<input type="file" accept="application/pdf" @change="choose"><small>Máximo 10 MB.</small></label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Registrando…':'Registrar fiscalización'}}</button></footer></form></div>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal detail"><header><div><small>{{tab==='fiscalizaciones'?'FICHA DE FISCALIZACIÓN':'FICHA DEL EXPEDIENTE PAS'}}</small><h2>{{tab==='fiscalizaciones'?(detail as Fiscalizacion).numero_fiscalizacion:(detail as ExpedientePas).numero_expediente}}</h2></div><button @click="detail=null">×</button></header><template v-if="tab==='fiscalizaciones'"><div class="summary"><div><b>{{(detail as Fiscalizacion).resultado_label||(detail as Fiscalizacion).resultado}}</b><span>Resultado</span></div><div><b>{{(detail as Fiscalizacion).estado}}</b><span>Estado</span></div><div><b>{{(detail as Fiscalizacion).medidas_correctivas?.length||0}}</b><span>Medidas correctivas</span></div></div><p class="facts">{{(detail as Fiscalizacion).descripcion_hechos}}</p><h3>Medidas correctivas</h3><div class="list"><p v-if="!(detail as Fiscalizacion).medidas_correctivas?.length">No existen medidas correctivas.</p><div v-for="x in (detail as Fiscalizacion).medidas_correctivas" :key="x.id"><b>{{x.descripcion}}</b><span>Vence: {{x.fecha_limite}}</span><em>{{x.estado}}</em></div></div></template><template v-else><div class="summary"><div><b>{{(detail as ExpedientePas).estado_label||(detail as ExpedientePas).estado_pas}}</b><span>Estado</span></div><div><b>{{(detail as ExpedientePas).res_inicio_numero||'Pendiente'}}</b><span>Resolución de inicio</span></div><div><b>{{money((detail as ExpedientePas).multa_soles)}}</b><span>Multa</span></div></div><p class="facts">Flujo: inicio → descargos → informe final de instrucción → resolución final → compromiso de cese o pago.</p></template><footer><button class="clear" @click="detail=null">Cerrar</button></footer></section></div></div></template>
<style scoped>
