d:#eff9f4}.cards article>small{margin-top:5px;color:#839097}.cards article>p{min-height:42px;color:#66757c;font-size:.56rem}.cards dl{display:flex;gap:14px}.cards dt{color:#8a969c;font-size:.47rem}.cards dd{margin:2px 0;font-size:.53rem;font-weight:700}.cards footer{margin-top:auto}.cards footer span{color:#a13f43;font-size:.49rem}.cards button,.table article>button{border:0;color:var(--accent);background:none;font-size:.52rem;font-weight:700}.table{margin-top:13px;border-radius:9px;background:#fff;overflow:hidden}.table>header,.table>article{padding:10px 12px;display:grid;grid-template-columns:1.1fr 1fr 1.2fr 85px 1fr 90px 65px;align-items:center;gap:8px}.table>header{color:#fff;background:var(--accent);font-size:.5rem;font-weight:700}.table>article{border-bottom:1px solid #edf0f2;font-size:.54rem}.table small{display:block;color:#7d898f}.danger{color:#b44747;font-weight:700}.empty{grid-column:1/-1;margin-top:13px;padding:45px;text-align:center;background:#fff;font-size:.63rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.55rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,800px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin-bottom:10px;font-size:.56rem}.modal label small{display:block;margin-top:4px;color:#89959b}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.check{display:flex!important;align-items:center;gap:7px}.check input{width:auto}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.summary{margin:14px 0;display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.summary div{padding:11px;text-align:center;border-radius:7px;background:#f0f3f5}.summary b,.summary span{display:block;font-size:.55rem}.facts{padding:12px;border-left:3px solid var(--accent);background:#f6f8f9;font-size:.6rem}.list div{padding:8px;display:grid;grid-template-columns:1fr 110px auto;gap:7px;align-items:center;border-bottom:1px solid #e8ecee;font-size:.56rem}.detail{width:min(100%,900px)}@media(max-width:900px){.cards{grid-template-columns:1fr 1fr}.table>header{display:none}.table>article{grid-template-columns:1fr 1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}@media(max-width:560px){.cards,.grid,.summary,.table>article{grid-template-columns:1fr}}
</style>
